def __str__(self):
        "Return the string representation of the Field."
        return str(self.value).strip()

def as_double(self):
        "Retrieve the Field's value as a double (float)."
        return (
            capi.get_field_as_double(self._feat.ptr, self._index)
            if self.is_set
            else None
        )

def as_int(self, is_64=False):
        "Retrieve the Field's value as an integer."
        if is_64:
            return (
                capi.get_field_as_integer64(self._feat.ptr, self._index)
                if self.is_set
                else None
            )
        else:
            return (
                capi.get_field_as_integer(self._feat.ptr, self._index)
                if self.is_set
                else None
            )

def as_string(self):
        "Retrieve the Field's value as a string."
        if not self.is_set:
            return None
        string = capi.get_field_as_string(self._feat.ptr, self._index)
        return force_str(string, encoding=self._feat.encoding, strings_only=True)

def as_datetime(self):
        "Retrieve the Field's value as a tuple of date & time components."
        if not self.is_set:
            return None
        yy, mm, dd, hh, mn, tz = [c_int() for _ in range(6)]
        ss = c_float()
        status = capi.get_field_as_datetime_x(
            self._feat.ptr,
            self._index,
            byref(yy),
            byref(mm),
            byref(dd),
            byref(hh),
            byref(mn),
            byref(ss),
            byref(tz),
        )
        if status:
            return (yy, mm, dd, hh, mn, ss, tz)
        else:
            raise GDALException(
                "Unable to retrieve date & time information from the field."
            )

def is_set(self):
        "Return True if the value of this field isn't null, False otherwise."
        return capi.is_field_set(self._feat.ptr, self._index)

def name(self):
        "Return the name of this Field."
        name = capi.get_field_name(self.ptr)
        return force_str(name, encoding=self._feat.encoding, strings_only=True)

def precision(self):
        "Return the precision of this Field."
        return capi.get_field_precision(self.ptr)

def type(self):
        "Return the OGR type of this Field."
        return capi.get_field_type(self.ptr)

def type_name(self):
        "Return the OGR field type name for this Field."
        return capi.get_field_type_name(self.type)

def value(self):
        "Return the value of this Field."
        # Default is to get the field as a string.
        return self.as_string()

def width(self):
        "Return the width of this Field."
        return capi.get_field_width(self.ptr)

def value(self):
        "Return an integer contained in this field."
        return self.as_int(self._bit64)

def value(self):
        "Return a float contained in this field."
        return self.as_double()

def value(self):
        "Return a Python `date` object for the OFTDate field."
        try:
            yy, mm, dd, hh, mn, ss, tz = self.as_datetime()
            return date(yy.value, mm.value, dd.value)
        except (TypeError, ValueError, GDALException):
            return None

def value(self):
        "Return a Python `time` object for this OFTTime field."
        try:
            yy, mm, dd, hh, mn, ss, tz = self.as_datetime()
            seconds = int(ss.value)
            milliseconds = int(round((ss.value - seconds) * 1000))
            return time(hh.value, mn.value, seconds, milliseconds * 1000)
        except (ValueError, GDALException):
            return None

