public StrBuilder clear() {
        size = 0;
        ArrayFill.clear(buffer);
        return this;
    }

public boolean contains(final char ch) {
        final char[] thisBuf = buffer;
        for (int i = 0; i < this.size; i++) {
            if (thisBuf[i] == ch) {
                return true;
            }
        }
        return false;
