void testEquals() {
        final StrBuilder sb1 = new StrBuilder();
        final StrBuilder sb2 = new StrBuilder();
        assertEquals(sb1, sb2);
        assertEquals(sb1, sb1);
        assertEquals(sb2, sb2);
        assertEquals(sb1, sb2);

        sb1.append("abc");
        assertNotEquals(sb1, sb2);
        assertNotEquals(sb1, sb2);

        sb2.append("ABC");
        assertNotEquals(sb1, sb2);
        assertNotEquals(sb1, sb2);

        sb2.clear().append("abc");
        assertEquals(sb1, sb2);
        assertEquals(sb1, sb2);

        assertNotEquals(sb1, Integer.valueOf(1));
        assertNotEquals("abc", sb1);
    }

void testEqualsIgnoreCase() {
        final StrBuilder sb1 = new StrBuilder();
        final StrBuilder sb2 = new StrBuilder();
        assertTrue(sb1.equalsIgnoreCase(sb1));
        assertTrue(sb1.equalsIgnoreCase(sb2));
        assertTrue(sb2.equalsIgnoreCase(sb2));

        sb1.append("abc");
        assertFalse(sb1.equalsIgnoreCase(sb2));

        sb2.append("ABC");
        assertTrue(sb1.equalsIgnoreCase(sb2));

        sb2.clear().append("abc");
        assertTrue(sb1.equalsIgnoreCase(sb2));
        assertTrue(sb1.equalsIgnoreCase(sb1));
        assertTrue(sb2.equalsIgnoreCase(sb2));

        sb2.clear().append("aBc");
        assertTrue(sb1.equalsIgnoreCase(sb2));

        // characters that only fold together via toLowerCase, matching String.equalsIgnoreCase
        sb1.clear().append("\u004B"); // LATIN CAPITAL LETTER K
        sb2.clear().append("\u212A"); // KELVIN SIGN, lower-cases to 'k'
        assertTrue(sb1.equalsIgnoreCase(sb2));
        assertTrue(sb2.equalsIgnoreCase(sb1));

        sb1.clear().append("\u00E5"); // LATIN SMALL LETTER A WITH RING ABOVE
        sb2.clear().append("\u212B"); // ANGSTROM SIGN, lower-cases to the same
        assertTrue(sb1.equalsIgnoreCase(sb2));
    }

void testGetChars () {
        final StrBuilder sb = new StrBuilder();

        char[] input = new char[10];
        char[] a = sb.getChars(input);
        assertSame (input, a);
        assertArrayEquals(new char[10], a);

        sb.append("junit");
        a = sb.getChars(input);
        assertSame(input, a);
        assertArrayEquals(new char[]{'j', 'u', 'n', 'i', 't', 0, 0, 0, 0, 0}, a);

        a = sb.getChars(null);
        assertNotSame(input, a);
        assertEquals(5, a.length);
        assertArrayEquals("junit".toCharArray(), a);

        input = new char[5];
        a = sb.getChars(input);
        assertSame(input, a);

        input = new char[4];
        a = sb.getChars(input);
        assertNotSame(input, a);
    }

void testGetCharsIntIntCharArrayInt() {
        final StrBuilder sb = new StrBuilder();

        sb.append("junit");
        final char[] a = new char[5];
        sb.getChars(0, 5, a, 0);
        assertArrayEquals(new char[]{'j', 'u', 'n', 'i', 't'}, a);

        final char[] b = new char[5];
        sb.getChars(0, 2, b, 3);
        assertArrayEquals(new char[]{0, 0, 0, 'j', 'u'}, b);

        assertIndexOutOfBoundsException(() -> sb.getChars(-1, 0, b, 0));
        assertIndexOutOfBoundsException(() -> sb.getChars(0, -1, b, 0));
        assertIndexOutOfBoundsException(() -> sb.getChars(0, 20, b, 0));
        assertIndexOutOfBoundsException(() -> sb.getChars(4, 2, b, 0));
    }

