public Set<String> resolve() {
			if (this.alignedVersions != null) {
				return this.alignedVersions;
			}
			Map<String, String> versions = resolveAligningDependencies();
			if (this.dependency != null) {
				String version = versions.get(this.dependency);
				this.alignedVersions = (version != null) ? Set.of(version) : Collections.emptySet();
			}
			else {
				Set<String> versionsInLibrary = new HashSet<>();
				for (Group group : this.groups) {
					for (Module module : group.getModules()) {
						String version = versions.get(group.getId() + ":" + module.getName());
						if (version != null) {
							versionsInLibrary.add(version);
						}
					}
					for (String plugin : group.getPlugins()) {
						String version = versions.get(group.getId() + ":" + plugin);
						if (version != null) {
							versionsInLibrary.add(version);
						}
					}
				}
				this.alignedVersions = versionsInLibrary;
			}
			return this.alignedVersions;
		}

private List<Dependency> getAligningDependencies() {
			if (this.managedBy == null) {
				Library fromLibrary = findFromLibrary();
				return List
					.of(this.project.getDependencies().create(this.from + ":" + fromLibrary.getVersion().getVersion()));
			}
			else {
				Library managingLibrary = findManagingLibrary();
				List<Dependency> boms = getBomDependencies(managingLibrary);
				List<Dependency> dependencies = new ArrayList<>();
				dependencies.addAll(boms);
				dependencies.add(this.project.getDependencies().create(this.from));
				return dependencies;
			}
		}

private Library findFromLibrary() {
			for (Library library : this.libraries) {
				for (Group group : library.getGroups()) {
					for (Module module : group.getModules()) {
						if (this.from.equals(group.getId() + ":" + module.getName())) {
							return library;
						}
					}
				}
			}
			return null;
		}

private Library findManagingLibrary() {
			if (this.managedBy == null) {
				return null;
			}
			return this.libraries.stream()
				.filter((candidate) -> this.managedBy.equals(candidate.getName()))
				.findFirst()
				.orElseThrow(() -> new IllegalStateException("Managing library '" + this.managedBy + "' not found."));
		}

private List<Dependency> getBomDependencies(Library manager) {
			if (manager == null) {
				return Collections.emptyList();
			}
			return manager.getGroups()
				.stream()
				.flatMap((group) -> group.getBoms()
					.stream()
					.map((bom) -> this.project.getDependencies()
						.platform(group.getId() + ":" + bom.name() + ":" + manager.getVersion().getVersion())))
				.toList();
		}

public String toString() {
			String result = "version from dependencies of " + this.from;
			if (this.managedBy != null) {
				result += " that is managed by " + this.managedBy;
			}
			return result;
		}

public Set<String> resolve() {
			if (this.alignedVersions != null) {
				return this.alignedVersions;
			}
			Configuration alignmentConfiguration = alignmentConfiguration(this.project, getAligningDependencies());
			Set<File> files = alignmentConfiguration.resolve();
			if (files.size() != 1) {
				throw new IllegalStateException(
						"Expected a single file when resolving the pom of " + this.from + " but found " + files.size());
			}
			File pomFile = files.iterator().next();
			return Set.of(propertyFrom(pomFile));
		}

private List<Dependency> getAligningDependencies() {
			Library managingLibrary = findManagingLibrary();
			List<Dependency> boms = getBomDependencies(managingLibrary);
			List<Dependency> dependencies = new ArrayList<>();
			dependencies.addAll(boms);
			dependencies.add(this.project.getDependencies().create(this.from + "@pom"));
			return dependencies;
		}

private Library findManagingLibrary() {
			if (this.managedBy == null) {
				return null;
			}
			return this.libraries.stream()
				.filter((candidate) -> this.managedBy.equals(candidate.getName()))
				.findFirst()
				.orElseThrow(() -> new IllegalStateException("Managing library '" + this.managedBy + "' not found."));
		}

private List<Dependency> getBomDependencies(Library manager) {
			return manager.getGroups()
				.stream()
				.flatMap((group) -> group.getBoms()
					.stream()
					.map((bom) -> this.project.getDependencies()
						.platform(group.getId() + ":" + bom.name() + ":" + manager.getVersion().getVersion())))
				.toList();
		}

private String propertyFrom(File pomFile) {
			try {
				Document document = XmlDocument.parse(pomFile);
				XPath xpath = XPathFactory.newInstance().newXPath();
				return xpath.evaluate("/project/properties/" + this.name + "/text()", document);
			}
			catch (Exception ex) {
				throw new RuntimeException(ex);
			}
		}

public String toString() {
			String result = "version from properties of " + this.from;
			if (this.managedBy != null) {
				result += " that is managed by " + this.managedBy;
			}
			return result;
		}

public String getReleaseTrainId() {
			return this.releaseTrainId;
		}

public record Link(String rootName, Function<LibraryVersion, String> factory, List<String> packages) {

		private static final Pattern PACKAGE_EXPAND = Pattern.compile("^(.*)\\[(.*)\\]$");

		public Link {
			packages = (packages != null) ? List.copyOf(expandPackages(packages)) : Collections.emptyList();
		}

		private static List<String> expandPackages(List<String> packages) {
			return packages.stream().flatMap(Link::expandPackage).toList();
		}

		private static Stream<String> expandPackage(String packageName) {
			Matcher matcher = PACKAGE_EXPAND.matcher(packageName);
			if (!matcher.matches()) {
				return Stream.of(packageName);
			}
			String root = matcher.group(1);
			String[] suffixes = matcher.group(2).split("\\|");
			return Stream.of(suffixes).map((suffix) -> root + suffix);
		}

		public String url(Library library) {
			return url(library.getVersion());
		}

		public String url(LibraryVersion libraryVersion) {
			return factory().apply(libraryVersion);
		}

	}

static List<String> expandPackages(List<String> packages) {
			return packages.stream().flatMap(Link::expandPackage).toList();
		}

static Stream<String> expandPackage(String packageName) {
			Matcher matcher = PACKAGE_EXPAND.matcher(packageName);
			if (!matcher.matches()) {
				return Stream.of(packageName);
			}
			String root = matcher.group(1);
			String[] suffixes = matcher.group(2).split("\\|");
			return Stream.of(suffixes).map((suffix) -> root + suffix);
		}

public String url(Library library) {
			return url(library.getVersion());
		}

public String url(LibraryVersion libraryVersion) {
			return factory().apply(libraryVersion);
		}

public record ImportedBom(String name, List<PermittedDependency> permittedDependencies) {

		public ImportedBom(String name) {
			this(name, Collections.emptyList());
		}

	}

public SortedSet<DependencyVersion> resolveVersions(String groupId, String artifactId, Library library) {
		Set<String> versions = new HashSet<>();
		for (MavenArtifactRepository repository : this.repositories) {
			versions.addAll(resolveVersions(groupId, artifactId, repository));
		}
		return versions.stream().map(DependencyVersion::parse).collect(Collectors.toCollection(TreeSet::new));
	}

private Set<String> resolveVersions(String groupId, String artifactId, MavenArtifactRepository repository) {
		Set<String> versions = new HashSet<>();
		URI url = UriComponentsBuilder.fromUri(repository.getUrl())
			.pathSegment(groupId.replace('.', '/'), artifactId, "maven-metadata.xml")
			.build()
			.toUri();
		try {
			String metadata = this.rest.get().uri(url).headers((headers) -> {
				PasswordCredentials credentials = credentialsOf(repository);
				String username = (credentials != null) ? credentials.getUsername() : null;
				if (username != null) {
					headers.setBasicAuth(username, credentials.getPassword());
				}
			}).retrieve().body(String.class);
			Document metadataDocument = XmlDocument.parseContent(metadata);
			NodeList versionNodes = (NodeList) XPathFactory.newInstance()
				.newXPath()
				.evaluate("/metadata/versioning/versions/version", metadataDocument, XPathConstants.NODESET);
			for (int i = 0; i < versionNodes.getLength(); i++) {
				versions.add(versionNodes.item(i).getTextContent());
			}
		}
		catch (HttpClientErrorException ex) {
			if (ex.getStatusCode() != HttpStatus.NOT_FOUND) {
				System.err.println("Failed to download maven-metadata.xml for " + groupId + ":" + artifactId + " from "
						+ url + ": " + ex.getMessage());
			}
		}
		catch (Exception ex) {
			System.err.println("Failed to resolve versions for module " + groupId + ":" + artifactId + " in repository "
					+ repository + ": " + ex.getMessage());
		}
		return versions;
	}

private PasswordCredentials credentialsOf(MavenArtifactRepository repository) {
		Credentials credentials = ((AuthenticationSupportedInternal) repository).getConfiguredCredentials().getOrNull();
		if (credentials != null) {
			if (credentials instanceof PasswordCredentials passwordCredentials) {
				return passwordCredentials;
			}
			throw new IllegalStateException("Repository '%s (%s)' has credentials '%s' that are not PasswordCredentials"
				.formatted(repository.getName(), repository.getUrl(), credentials));
		}
		return null;
	}

